import json

# Derive the Phan Rang Cham (PRC) form of *dəpa "fathom" from the attested
# correspondences in the table. Only the PRC column is needed for the masked element (6).

# Attested initial/vowel/stress regularities in the given data:
#   d-  -> t-   (*dikiʔ -> takiʔ, *dilah -> talàh, *dua -> ... (d- -> t- in PRC))
#   ə   -> a    (*bəsey -> pathey is the only ə-form; *bubah -> papàh shows
#                unstressed/reduced vowels rendered as a)
#   p   -> p    (*bara -> pirà, *bubah -> papàh, *labaːt -> lipàʔ, *padam -> patàm)
#   a   -> a    (*dalam-type finals; *padam -> patàm, *paday -> patày)
#   Disyllabic PRC forms carry grave stress on the final syllable
#   (talàh, calàn, pirà, piròw, pilòw, patàm, patày, tapùh, tatà).

INITIAL = {"d": "t"}
VOWEL = {"ə": "a", "a": "a"}
CONSONANT = {"p": "p"}
FINAL_STRESS = {"a": "à"}

def pra_to_prc(syllables):
    # syllables: list of (onset, vowel) pairs for the disyllable
    out = []
    for i, (onset, vowel) in enumerate(syllables):
        o = INITIAL.get(onset, CONSONANT.get(onset, onset)) if i == 0 else CONSONANT.get(onset, onset)
        v = VOWEL.get(vowel, vowel)
        if i == len(syllables) - 1:
            v = FINAL_STRESS.get(v, v)
        out.append(o + v)
    return "".join(out)

# *dəpa -> syllables (d,ə)(p,a)
form = pra_to_prc([("d", "ə"), ("p", "a")])

result = {
    "final_answer": form,
    "evidence": {
        "proto": "*dəpa",
        "rules": ["d->t initial", "ə->a", "p->p", "final syllable stressed (grave)"],
        "support": ["*dikiʔ->takiʔ", "*dilah->talàh", "*bubah->papàh", "*padam->patàm"],
        "masked": 6,
    },
}

print(json.dumps(result, ensure_ascii=False))
